Common Use of Unions 
• Union within struct 
struct student{ 
union grade{ 
int percentage_grade; //ex: 99% 
char letter_grade; // 'B' 
}; 
int grade_format; // I set to 0 if grade is int, 1 if grade is 
char 
}; 
struct student frank; 
frank.grade.percentage_grade = 90; 
frank.grade_format = 0; 
